import { mkdirSync } from 'node:fs';
import { join } from 'node:path';
import Database from 'better-sqlite3';
import {
  drizzle,
  type BetterSQLite3Database,
} from 'drizzle-orm/better-sqlite3';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import * as schema from './schema';

export type AppDatabase = BetterSQLite3Database<typeof schema> & {
  $client: Database.Database;
};

export const DATABASE = Symbol('DATABASE');

/**
 * SQL migrations generated by drizzle-kit. They sit next to this file in the
 * sources and next to the bundle in the build output (see webpack.config.js).
 */
export const MIGRATIONS_DIR = join(__dirname, 'migrations');

export const DATABASE_FILE_NAME = 'claude-remote-manager.sqlite';

/**
 * Opens (or creates) the database and applies pending migrations. Pass
 * `':memory:'` for a throwaway database in tests.
 */
export function openDatabase(
  location: string,
  migrationsDir = MIGRATIONS_DIR,
): AppDatabase {
  let file = location;
  if (location !== ':memory:') {
    mkdirSync(location, { recursive: true });
    file = join(location, DATABASE_FILE_NAME);
  }
  const client = new Database(file);
  client.pragma('journal_mode = WAL');
  client.pragma('foreign_keys = ON');
  const db = drizzle({ client, schema });
  migrate(db, { migrationsFolder: migrationsDir });
  return db;
}
